import { test, expect } from '@playwright/test';

test.describe('Duplicate Record Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully duplicate an existing record with one click', async ({ page }) => {
    // Verify initial record count
    const recordCount = page.getByRole('heading', { name: /records/i }).count();
    expect(recordCount).toBeGreaterThan(0);

    // Verify first record is visible
    const firstRecord = page.getByText('Record 1');
    await expect(firstRecord).toBeVisible();

    // Verify duplicate button is visible
    const duplicateButton = page.getByRole('button', { name: /duplicate/i });
    await expect(duplicateButton).toBeVisible();

    // Click duplicate button
    await duplicateButton.click();

    // Verify duplicate record appears
    const duplicateRecord = page.getByText('Record 1 - Copy');
    await expect(duplicateRecord).toBeVisible();

    // Verify duplicate record has unique ID
    const originalId = page.getByRole('heading', { name: /record 1/i }).first().textContent().match(/\d+/);
    const duplicateId = page.getByRole('heading', { name: /record 1 - copy/i }).first().textContent().match(/\d+/);
    expect(originalId).not.toBe(duplicateId);

    // Verify duplicate record is listed
    const duplicateRecordList = page.locator('[data-testid="record-list"]');
    await expect(duplicateRecordList).toContainText('Record 1 - Copy');

    // Verify duplicate record has same data as original
    const originalRecordData = page.getByRole('heading', { name: /record 1/i }).first().textContent().match(/\d+/);
    const duplicateRecordData = page.getByRole('heading', { name: /record 1 - copy/i }).first().textContent().match(/\d+/);
    expect(originalRecordData).toBe(duplicateRecordData);

    // Verify duplicate record has same edit/delete options
    const editButton = page.getByRole('button', { name: /edit/i });
    await expect(editButton).toBeVisible();
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await expect(deleteButton).toBeVisible();
  });

  test('should handle duplicate of non-existent record gracefully', async ({ page }) => {
    // Verify no records are displayed initially
    const recordCount = page.getByRole('heading', { name: /records/i }).count();
    expect(recordCount).toBe(0);

    // Click duplicate button on empty state
    const duplicateButton = page.getByRole('button', { name: /duplicate/i });
    await expect(duplicateButton).toBeVisible();
    await duplicateButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/no records to duplicate/i);
    await expect(errorMessage).toBeVisible();

    // Verify duplicate button is still visible
    await expect(duplicateButton).toBeVisible();

    // Verify no duplicate record is created
    const duplicateRecord = page.getByText('Record 1 - Copy');
    await expect(duplicateRecord).not.toBeVisible();

    // Verify original error message is still present
    await expect(errorMessage).toBeVisible();
  });
});
